let stored: string | null = null;
try { stored = typeof window !== 'undefined' ? window.localStorage.getItem('ggs:locale') : null; } catch { stored = null; }
const browser = typeof navigator !== 'undefined' ? navigator.language : 'en';
const detected = browser.toLowerCase().startsWith('zh') ? 'zh-CN' : browser.slice(0, 2);
const firstVisitLocale = ['es', 'fr', 'zh-CN'].includes(detected) ? detected : 'en';

void i18n.use(initReactI18next).init({
  resources, lng: stored || firstVisitLocale, fallbackLng: 'en', supportedLngs: ['en', 'es', 'fr', 'zh-CN'],
  interpolation: { escapeValue: false }, returnNull: false,
});

i18n.on('languageChanged', (language) => {
  if (typeof document !== 'undefined') {
    document.documentElement.lang = language;
    document.documentElement.dir = i18n.dir(language);
  }
  try { if (typeof window !== 'undefined') window.localStorage.setItem('ggs:locale', language); } catch { /* Locale still applies for this session. */ }
});
if (typeof document !== 'undefined') {
  document.documentElement.lang = i18n.language;
  document.documentElement.dir = i18n.dir(i18n.language);
}

export default i18n;
